INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1054129-coe344', 'stk-iiiii', 'COE 344', 'info', '{"desc": "جودة المقرر بشكل عام: جيد\nالمواضيع التي يغطيها المقرر: كورس يتكلم عن الشبكات ويغطي اغلب مواضيعها طبعاً الكورس شوي طويل ويحتاج شغل ويعتمد على الدكتور … وايضا يعتمد على كل واحد اذا عنده خبره في التعامل مع الشبكات بيكون الكورس عليه أسهل … وهو كورس اساسي للي يبي يتخصص شبكات وجداً مهم إذا فهمته بترتاح كثير وتستفيد … اللاب تطبيقي ومفيد على الشبكات …\nالكتاب المستخدم للمقرر: بالنسبه لي ماعجبني الكتاب …\nالأسئلة والأمثلة المستخدمة في المقرر: السورسات فيه قليله يبيلك تبحث وتطبق على اسئلة الهومورك والكورس مثل ماقلت من قبل يعتمد على الدكتور وطريقته …\n\nمدى فائدته في الناحية التطبيقية: مهم جداُ جداً واغلب شكل مهندسين الحاسب على الشبكات وفي التطبيق وفي العمل بترجع كثير لمراجع الماده …\n\nالخلاصه ان الكورس مهم جداً وفهمه يفيدك ويوفر عليك الكثير … لكن مشكلته شوي طويل وعلى حسب الدكتور … والماده حلوه وتعتمد من شخص لشخص فيه ناس استثقلوها وناس حبوا الماده وعندك مواد اختياريه بعدها في الشبكات مثل الـ 446 في الوايرلس, 441 في الـ lan , الـ 444 في تصميم وادارة الشبكات وغيرها من الكورسات … فكل واحد ورغبته …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coe-344-computer-networks/120818/2", "user": "IIIII", "ts": 1339420285000, "tid": 120818, "pn": 2}}', 1339420285000, 1794826849, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1157564-coe344', 'stk-maaf4ever', 'COE 344', 'info', '{"desc": "المادة باختصار تتكلم عن الشبكات ، كيف البيانات تنرسل من جهاز لجهاز ثاني مرور بال 7 ليرز المدروسه بال 341\nتتكلم عن الوايرلس شبكات الجوال ، لما يضيع فريم وقت الارسال ايش الحاجات المترتبة عليه.\nالكورس حلو صحيح مليان معلومات بس كلها شرح لشي واحد ، اقصد ان التشابتر يتكلم عن 5 او 6 معلومات بس وتحصله مشروح ب 80 سلايد ! 🙂 يعني الافكار الرئيسية بالكورس قليلة وممكن تحصلها بشهر واحد !", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coe-344-computer-networks/120818/3", "user": "maaf4ever", "ts": 1357530845000, "tid": 120818, "pn": 3}}', 1357530845000, 1794826849, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1292511-coe344', 'stk-sultan11', 'COE 344', 'info', '{"desc": "كورس دسم جداً . زي ما قالوا الشباب يعتمد نسبياً على الـ 341 ( 241 ) …\n\nاللي يقدمه هو الدكتور بو عمارة .\n\nالكورس بالنسبة لي كان ثقيل جداً و دسم جداً .\n\nالكورس يتكلم عن النتووركنق في الثلاث طبقات الأخيرة :Network, Datalink & Physical layer\n\nالكورس يتكلم عن الـ Ethernet و طرق معالجة تصادم البيانات في الكابل أو الهواء . أيضاً يتكلم عن الـ Device homing في الشبكات اللاسلكية و بعيدة المدى . يتكلم أيضاً عن الـ Routing و الـ Routing protocols .\n\nباختصار الكورس ثقيل . جهّز مخك لتقبل معلومات كثيرة … جداً .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coe-344-computer-networks/120818/4", "user": "Sultan11", "ts": 1385174007000, "tid": 120818, "pn": 4}}', 1385174007000, 1794826849, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1473404-coe344', 'stk-ali_haitham', 'COE 344', 'info', '{"desc": "جودة المقرر بشكل عام:\nالمقرر هو شي اساسي لا يتجزأ من مهام مهندس الحاسب يتكلم عن شبكات الحاسب الالي و هو تكملة لمقرر COE241\nالمواضيع التي يغطيها المقرر:\nيغطي TCP/IP layers\neach layer in one chapter.\nيبدأ بال Application layer و يغطي البروتكولات الموجودة فيها مثل HTTP, SMTP, DNS\nبعدها يتكلم عن ال Transport layer و يتكلم عن TCP and UDP\nو بعدها Network layer ويشرح IP protocol\nو اخير يغطي ال Datalink layer\nالكتاب المستخدم للمقرر\nComputer Networking , A top down approach\nالأسئلة والأمثلة المستخدمة في المقرر:\nالكتاب غني بالاسئلة و الامثلة، و طريقة عرض الكتاب جدا ممتعة\n(الكتاب و شرحه يغني عن المدرس)\nمدى فائدته في الناحية التطبيقية:\nمن اكثر المواضيع المهمة خصوصا بالناحية التطبيقية، في وقت الحوسبة لا يخلوا اي مكان من الانترنت و الاتصالات. تطبيقاتها لها مجالات كبيرة من بناء برامج تتصل بالانترنت الى بناء الشبكات.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coe-344-computer-networks/120818/6", "user": "Ali_Haitham", "ts": 1495187536000, "tid": 120818, "pn": 6}}', 1495187536000, 1794826849, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p133448-coe344', 'stk-user452', 'COE 344', 'info', '{"desc": "الصراحة المادة رائعة جدا جدا جدا جدا …\n\nوهي أصل الشبكات … خاصة إن فيها لاب من أروع اللابات …\n\nعلى كل حال …\n\nالمدرسين روعة في الأخلاق والتعامل راقي …\n\nوالمدرسين في هذه المادة أغلب أسئلتهم من الكتاب …\n\nلكن خلني أقول لك اللي عندي وانت اختر اللي تبي …\n\nأبو عمارة …\nدرسنيCOMPUTER NETWORKS قبل سنتين ونص .\nمدرس حبيب وثقيل … فاهم المادة … أسئلته من الكتاب … مافيه واجبات … شرحه عادي من السلايد …\nحصته تجيب النوم … والمشكلة إذا كانت أحد وثلوث …\nالدرجات ما يظلمك ولا يزيدك حقك …\n\nطارق شلطامي\nدرسني mobile computing قبل سنة ونص\nمدرس حبيب … خفيف دم من جد … فاهم المادة … أسئلته من الكتاب … يعطي واجبات … شرحه عادي من السلايد … يطالع فوق … ينكت كثير … يحب الطلاب\nحصته تجيب حماس …\nالدرجات يحرص عليك و يزيدك فوق حقك …\n\nعاد هالحين انت وخيارك …\n\nإذا تبي تطلع كوأب أنصحك بشركة SBM … وإذا أنت مجزم الغرفة التجارية … وإذا تبي تكرف أرامكو …\n\nولك تحياتي من أخوووووووووووووك خلووووووووووووووووووها", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coe-344/53403/3", "user": "user452", "ts": 1164244777000, "tid": 53403, "pn": 3}}', 1164244777000, 1794826849, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8697-coe344', 'stk-user8697', 'COE 344', 'doc', '{"docs": [{"id": "stk-dr-f98335", "n": "Dr. Uthman Abdurrahman Baroudi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 141 - COE344\n\nالتحضير : يوميا مع بعض التساهل\nطريقة الشرح : سلايدز + سبورة عند الحاجة\nالكويزات : سهلة إلى متوسطة حسب الفهم\nالمياجر: سهلة جدا ( اغلبها أسئلة مكررة من اختبارات سابقة)\nالفاينلات : نفس المياجر\nالقريد النهائي: A\nالصوت: واضح\nإضافات : طريقة شرح الدكتور مملة قليلا لكن شرحه جدا ممتاز", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1426412-coe344", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-uthman-abdurrahman-baroudi/98335/19", "user": "user8697", "ts": 1440881305000, "tid": 98335, "pn": 19}}]}', 1440881305000, 1794826849, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ali_haitham-coe344', 'stk-ali_haitham', 'COE 344', 'doc', '{"docs": [{"id": "stk-dr-f98338", "n": "Dr. Ashraf S. Hasan Mahmoud", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "COE344- 162\n\nالتحضير :\nنهاية كل كلاس\nطريقة الشرح :\nيستعمل سلايدات الكاتب، ،يصحح الاخطاء الموجودة فيها ويعطي بونصات للي يشارك (درجة في الفاينل)\nيربط الماتريال بالواقع خصوصا مع شركات الاتصال(STC, Zain, etc) و هيئة الاتصالات و يعطي امثلة عن نظام الاتصالات في الغرب\n\nالكويزات :\nيستعمل الكتاب و السلايدات، ركز على امثلة الكتاب راح يجيب اشياء قريبة منها\nالمياجر:\nمن الهوموركات و الكويزات والمتيريال اللي ركز عليه بالكلاس\nالفاينلات :\nNot yet\nالقريد النهائي:\nA+\nالصوت:\nواضح\nإضافات :\nالدكتور أشرف من أفضل الدكاترة اللي درست عندهم، الدكتور يقدر الطلاب و يحترمهم و متعاون معاهم و يحب الطلاب يبحثوا في الموضوع و يتفاعلوا بالكلاس،\n**اذا نزل اي مادة نزلها معاه و ما بتندم **", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1473402-coe344", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-ashraf-s-hasan-mahmoud/98338/6", "user": "Ali_Haitham", "ts": 1495186669000, "tid": 98338, "pn": 6}}]}', 1495186669000, 1794826849, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-coe344', 'stk-guest', 'COE 344', 'doc', '{"docs": [{"id": "stk-dr-f115387", "n": "Dr. Hakim Adiche", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "COE 344 LAB - 191\nالتحضير : نسيت\nطريقة الشرح : يبث شاشته على كل الكمبيوترات في اللاب ويشرح لك ويرسم في شاشة الكمبيوتر اذا احتاج\nالكويزات : اربع كويزات وياخذ احسن ثلاثة\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: D+\nالصوت: صغير في اللاب الكبير وكلامه سرييييييييييييييييييييييييييييييييع بعض المرات صعب تفهمه\nإضافات : للاسف انه الوحيد اللي يدرس اللاب\nلازم تكتب معاه ملاحظات ولازم ترسم ديقرام ويصحح نوتاتك وعليها درجات وتصحيحه جدا غريب\nيحاسبك على ملاحظاتك! يحاسبك على الديقرام، على اي شي\nيزعل اذا ما سألته، واذا سألته قال لك انت وزميلك اثنين وعندكم مخين ليش ما تقدرون تحلون\nيهزء كثير ويخلي الطالب يمل من كثر التهزيء، ليش ما تسأل، ليش ما تكتب، ليش ما تسوي كذا، ليش تسوي كذا…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1526765-coe344", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-hakim-adiche/115387/9", "user": "Guest", "ts": 1606024575000, "tid": 115387, "pn": 9}}]}', 1606024575000, 1794826849, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
